ONLINE = {'RLHF', 'PPO', 'GRPO'}
COMPONENTS = {
    'RLHF': [True, False],
    'PPO': [True, True],
    'GRPO': [False, False],
    'DPO': [False, False],
}


def needs_online(method):
    if method not in COMPONENTS:
        raise ValueError('unknown method: ' + method)
    return method in ONLINE


def needs_components(method):
    if method not in COMPONENTS:
        raise ValueError('unknown method: ' + method)
    return list(COMPONENTS[method])

print(needs_online('DPO'), needs_components('PPO'))

def advantages(rewards):
    n = len(rewards)
    mean = sum(rewards) / n
    var = sum((r - mean) ** 2 for r in rewards) / n
    sd = var ** 0.5
    if sd == 0:
        return None
    return {i: (r - mean) / sd for i, r in enumerate(rewards)}

print(advantages([1.0, 2.0, 3.0, 4.0]))
